const root="/home/axel/LeanAlgebraicGeometry-Horizon";
const queries=["Scheme.Pic0.isProjective_for_kleimanQppAndP","orbitsInAffineOpen_of_isProjective","finiteInAffine_of_isProjective","isHQuasiProjective","Pic0.isProjective","pic0 projective kleiman","pic0RepresentableBy_finiteGaloisDescent"];
for (const q of queries) {
 const r=await tools.exec_command({cmd:`"$HORIZON_BIN" search --name ${JSON.stringify(q)} --limit 60 --json`,workdir:root,yield_time_ms:30000,max_output_tokens:25000});
 text(`==${q}==\n${r.output}`);
}

const root="/home/axel/LeanAlgebraicGeometry-Horizon";
const qs=[
 ["p","Pic0PreservesFilteredBaseColimit ?C"],
 ["f","Scheme.FiniteInAffine ?X"],
 ["o","?rho.OrbitsInAffineOpen"],
 ["proj","?pi.IsProjective"],
 ["hq","?pi.IsHQuasiProjective"]
];
const rs=await Promise.all(qs.map(async ([k,q])=>[k,await tools.exec_command({cmd:`"$HORIZON_BIN" search --type ${JSON.stringify(q)} --limit 100 --json`,workdir:root,yield_time_ms:30000,max_output_tokens:40000})]));
for(const [k,r] of rs) text(`==${k}==\n${r.output}`);

const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const rs=await Promise.all([
 tools.exec_command({cmd:"sed -n '1,280p' AlgebraicJacobian/Descent/GroupAffineOpen.lean",workdir:wd,yield_time_ms:10000,max_output_tokens:30000}),
 tools.exec_command({cmd:"sed -n '1,340p' AlgebraicJacobian/Picard/PicRepColimitMountain.lean",workdir:wd,yield_time_ms:10000,max_output_tokens:30000}),
 tools.exec_command({cmd:"rg -n \"finiteInAffine_of_isAlgClosed|GroupAffineOpen|IrreducibleSpace.*Pic0|GrpObj.*pic0|pic0.*GrpObj|commGrp\" AlgebraicJacobian",workdir:wd,yield_time_ms:10000,max_output_tokens:30000})
]);
text("==group==\n"+rs[0].output); text("==mountain==\n"+rs[1].output); text("==uses==\n"+rs[2].output);

